<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>SIRKA – Sistem Informasi Surat Koperasi</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
:root{--bg:#E8EEF8;--shell:rgba(255,255,255,.92);--panel:#fff;--line:#E1E9F6;--tline:#E6ECF6;--ink:#0B1B3F;--text:#334155;--mute:#64748B;--thead:#EEF2F8;--thc:#334155;--alt:#F8FAFD;--inp:#fff;--inpb:#D7E0F0;--hl:rgba(255,255,255,.95);--sh:0 10px 24px -16px rgba(30,70,160,.4);--a1:#0A6CFF;--a2:#F0364F;--a3:#E08A00;--acc:#0A6CFF;--accb:#0A5BD3;
--k1:linear-gradient(135deg,#F3F8FF 0%,#E2EEFF 100%);--k1i:#DCEBFF;--k1ic:#1E6BFF;--k1w:rgba(110,175,255,.55);--k1c:#1E6BFF;--k1b:#D3E3FA;
--k2:linear-gradient(135deg,#FFF7F9 0%,#FFE8EC 100%);--k2i:#FFDDE3;--k2ic:#F0364F;--k2w:rgba(255,130,160,.5);--k2c:#F0364F;--k2b:#F8D1D9;
--k3:linear-gradient(135deg,#FFFCEE 0%,#FFF0C6 100%);--k3i:#FFEDB8;--k3ic:#F59E0B;--k3w:rgba(255,196,60,.6);--k3c:#E08A00;--k3b:#F5E0A0;
--okb:#DDF7E8;--okc:#14803F;--nb:#DCEBFF;--nc:#0A6CFF;--wb:#FFEDB8;--wc:#A15F00;--rb:#FFDDE3;--rc:#C8203A;--gb:#EEF1F6;--gc:#5B6B84;color-scheme:light}
@media (prefers-color-scheme:dark){:root{--bg:#040B18;--shell:rgba(14,30,56,.55);--panel:#0D1C33;--line:#1B2E4F;--tline:#1F3250;--ink:#FFFFFF;--text:#D6E0F2;--mute:#97ABCB;--thead:#13264A;--thc:#B9C8E4;--alt:#0F2038;--inp:#0A172C;--inpb:#243A5E;--hl:rgba(255,255,255,.12);--sh:0 12px 26px -16px rgba(0,0,0,.9);--a1:#2D86FF;--a2:#FF6B8D;--a3:#FFC043;--acc:#2D86FF;--accb:#1E6BFF;
--k1:linear-gradient(135deg,#0B3F8C 0%,#062A5E 100%);--k1i:linear-gradient(145deg,#3B9AFF,#0A5BD3);--k1ic:#fff;--k1w:rgba(70,150,255,.35);--k1c:#4DA3FF;--k1b:#16417F;
--k2:linear-gradient(135deg,#8C2340 0%,#4C142C 100%);--k2i:linear-gradient(145deg,#FF5C82,#C9183F);--k2ic:#fff;--k2w:rgba(255,100,140,.3);--k2c:#FF6B8D;--k2b:#6B2140;
--k3:linear-gradient(135deg,#855712 0%,#47310F 100%);--k3i:linear-gradient(145deg,#FFC94D,#E08A00);--k3ic:#fff;--k3w:rgba(255,190,70,.3);--k3c:#FFC043;--k3b:#6B4A14;
--okb:#0F3A2A;--okc:#6EE7A8;--nb:#0B3A78;--nc:#7DBBFF;--wb:#47310F;--wc:#FFC043;--rb:#4C142C;--rc:#FF6B8D;--gb:#1A2A45;--gc:#D0DBEF;color-scheme:dark}}
*{box-sizing:border-box}
html{scroll-padding-top:env(safe-area-inset-top,0px)}
:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 'Inter',system-ui,-apple-system,'Segoe UI',sans-serif;-webkit-font-smoothing:antialiased}
.app{max-width:1180px;margin:0 auto;padding:14px;display:flex;flex-direction:column;gap:12px;min-height:100vh}
.top{background:var(--panel);border:1.5px solid var(--line);border-radius:20px;display:flex;align-items:center;gap:16px;padding:10px 18px;box-shadow:inset 0 2px 0 var(--hl),var(--sh);flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:10px}
.lg{width:38px;height:38px;border-radius:12px;background:linear-gradient(145deg,#4DA3FF,#0A5BD3);color:#fff;display:grid;place-items:center;font-weight:800;font-style:italic;box-shadow:inset 0 2px 0 rgba(255,255,255,.4),0 4px 8px -2px rgba(10,91,211,.5)}
.brand b{display:block;font-size:17px;letter-spacing:.04em;color:var(--ink);line-height:1.1}.brand span{font-size:11.5px;color:var(--mute)}
.nav{display:flex;gap:6px;flex:1;flex-wrap:wrap}
.nav button{font:500 13.5px inherit;font-family:inherit;border:1px solid var(--line);background:var(--panel);color:var(--text);padding:7px 14px;border-radius:999px;cursor:pointer}
.nav button.on{background:var(--acc);color:#fff;border-color:transparent;box-shadow:0 3px 0 rgba(0,0,0,.2)}
.me{display:flex;align-items:center;gap:10px;padding-left:16px;border-left:1.5px solid var(--line)}
.av{width:36px;height:36px;border-radius:50%;background:linear-gradient(145deg,#4DA3FF,#0A5BD3);color:#fff;display:grid;place-items:center;font-weight:600;box-shadow:inset 0 2px 0 rgba(255,255,255,.4)}
.me b{display:block;font-size:14px;color:var(--ink);line-height:1.2}.me span{font-size:12px;color:var(--mute)}
.body{flex:1;background:var(--shell);border:1.5px solid var(--line);border-radius:28px;box-shadow:inset 0 2px 0 var(--hl),var(--sh);padding:18px 22px 22px;display:none;flex-direction:column;gap:14px}
.body.on{display:flex}
.head{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap}
h1{margin:0;font-size:28px;font-weight:600;letter-spacing:-.02em;line-height:1.2;color:var(--ink)}
.crumb{font-size:13.5px;color:var(--mute);margin-top:4px}.crumb a{color:var(--acc);font-weight:500;padding:2px 12px;border-radius:999px;border:1px solid var(--line);background:var(--panel)}
.btn{font:600 14px inherit;font-family:inherit;color:#fff;border:0;border-radius:14px;padding:10px 18px;cursor:pointer;background:linear-gradient(145deg,#4DA3FF,#0A5BD3);box-shadow:inset 0 2px 0 rgba(255,255,255,.35),0 3px 0 #0A4DB5,0 12px 18px -8px rgba(10,91,211,.7)}
.btn:active{transform:translateY(2px);box-shadow:inset 0 2px 0 rgba(255,255,255,.35),0 1px 0 #0A4DB5}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;padding:3px}
.card{--k:var(--k1);--ki:var(--k1i);--kc:var(--k1c);--kb:var(--k1b);--kw:var(--k1w);position:relative;background:var(--k);border:1.5px solid var(--kb);border-radius:22px;padding:14px 18px 12px 80px;cursor:pointer;transition:.15s;box-shadow:0 14px 24px -16px var(--kc),inset 0 2px 0 var(--hl),inset 0 -4px 8px -4px var(--kw)}
.card.r{--k:var(--k2);--ki:var(--k2i);--kc:var(--k2c);--kb:var(--k2b);--kw:var(--k2w)}
.card.a{--k:var(--k3);--ki:var(--k3i);--kc:var(--k3c);--kb:var(--k3b);--kw:var(--k3w)}
.card:hover{transform:translateY(-3px);box-shadow:0 0 0 2px var(--kc),0 20px 30px -14px var(--kc),inset 0 2px 0 var(--hl)}
.ic{position:absolute;left:18px;top:16px;width:46px;height:46px;border-radius:15px;background:var(--ki);color:var(--kc);display:grid;place-items:center;box-shadow:inset 0 2px 0 rgba(255,255,255,.5),0 8px 14px -6px var(--kc)}
.ic svg{width:24px;height:24px}
.card .t{font-size:13.5px;font-weight:500;color:var(--ink)}.card .n{font-size:36px;font-weight:600;line-height:1.15;letter-spacing:-.02em;color:var(--ink)}.card .n small{font-size:14px;font-weight:400;margin-left:8px;color:var(--mute)}.card .d{font-size:12.5px}.card .go{text-align:right;font-size:12.5px;font-weight:600;color:var(--kc)}
.pnl{background:var(--panel);border:1.5px solid var(--line);border-radius:22px;box-shadow:inset 0 2px 0 var(--hl),var(--sh)}
.strip{display:flex;gap:44px;padding:12px 24px;flex-wrap:wrap}.strip span{display:block;font-size:12.5px;color:var(--mute)}.strip b{font-size:19px;font-weight:600;color:var(--ink)}
.split{display:flex;gap:14px;align-items:flex-start;flex-wrap:wrap}
.tbl{flex:1;min-width:300px;overflow:hidden}
.th{padding:14px 20px 10px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.th h3{margin:0;font-size:17px;font-weight:600;color:var(--ink)}
.search{border:1.5px solid var(--inpb);background:var(--inp);color:var(--ink);border-radius:14px;padding:7px 14px;font:13.5px inherit;font-family:inherit;width:190px}
.sc{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:14px}
th{text-align:left;font-weight:700;font-size:12.5px;color:var(--thc);background:var(--thead);padding:11px 14px;white-space:nowrap;border-bottom:2px solid var(--acc)}
td{padding:12px 14px;border-bottom:1px solid var(--tline);white-space:nowrap;color:var(--ink);font-weight:500}
td:first-child{font-weight:600}tbody tr:nth-child(even) td{background:var(--alt)}tbody tr{cursor:pointer}tbody tr:hover td{background:var(--thead)}
.tag{display:inline-block;padding:2px 12px;border-radius:999px;font-size:12px;font-weight:600}
.s-n{background:var(--nb);color:var(--nc)}.s-w{background:var(--wb);color:var(--wc)}.s-ok{background:var(--okb);color:var(--okc)}.s-r{background:var(--rb);color:var(--rc)}.s-g{background:var(--gb);color:var(--gc)}
.side{width:260px;flex:none;padding:16px;display:flex;flex-direction:column;gap:10px}
.side h3{margin:0;font-size:16px;color:var(--ink)}.side p{margin:0;font-size:13px}
.pdf{height:130px;border-radius:14px;border:1.5px dashed var(--line);background:var(--alt);display:grid;place-items:center;text-align:center;color:var(--mute);font-size:12.5px}
.pdf b{display:block;color:var(--rc);font-size:22px;letter-spacing:.05em}
.row{display:flex;justify-content:space-between;font-size:13px;gap:8px}.row span{color:var(--mute)}.row b{color:var(--ink);text-align:right;font-weight:600}
.act{display:flex;flex-direction:column;gap:10px;padding:6px 20px 16px}
.it{display:flex;gap:12px;font-size:13.5px}.dot{width:10px;height:10px;border-radius:50%;margin-top:6px;flex:none;background:var(--acc)}.it span{display:block;color:var(--mute);font-size:12px}
#login{padding:0;flex-direction:row;overflow:hidden;min-height:560px}
.hero{flex:1.1;min-width:300px;padding:44px;color:#fff;display:flex;flex-direction:column;justify-content:space-between;gap:30px}
.hero h2{font-size:38px;line-height:1.2;margin:0 0 14px;font-weight:600;letter-spacing:-.02em;max-width:420px}.hero p{margin:0;max-width:380px;line-height:1.65;opacity:.9}
.fw{flex:1;min-width:300px;display:grid;place-items:center;padding:30px}
.form{width:100%;max-width:380px;background:var(--panel);border:1.5px solid var(--line);border-radius:28px;padding:34px;box-shadow:inset 0 2px 0 var(--hl),0 28px 50px -22px rgba(5,40,35,.55)}
.form h2{font-size:28px;margin:0 0 6px;color:var(--ink);font-weight:600;letter-spacing:-.02em}.form p{margin:0 0 22px;color:var(--mute);font-size:15px}
label{display:block;font-weight:500;font-size:14px;margin-bottom:6px}
input.f{width:100%;height:50px;border-radius:16px;border:1.5px solid var(--inpb);background:var(--inp);color:var(--ink);padding:0 16px;font:16px inherit;font-family:inherit;margin-bottom:16px}
input:focus,button:focus-visible{outline:3px solid #7DB3FF;outline-offset:2px}
.form .btn{width:100%;height:52px;font-size:16px;margin-top:4px}
.top[hidden]{display:none}
@media(max-width:700px){.hero{display:none}.me{border:0;padding:0}h1{font-size:24px}}

.fm{padding:22px}.fg{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:0 18px}.fg .full{grid-column:1/-1}
select.f{width:100%;height:50px;border-radius:16px;border:1.5px solid var(--inpb);background:var(--inp);color:var(--ink);padding:0 14px;font:16px inherit;font-family:inherit;margin-bottom:16px}textarea.f{height:auto;padding:12px 16px;resize:vertical}
.acts{display:flex;gap:10px;justify-content:flex-end;margin-top:4px}
.btn.g{background:var(--panel);color:var(--text);border:1.5px solid var(--line);box-shadow:0 3px 0 var(--line)}
.files{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px}
.fc{padding:14px;display:flex;flex-direction:column;gap:8px}.fc .pdf{height:90px}.fc h4{margin:0;font-size:14px;color:var(--ink)}.fc p{margin:0;font-size:12.5px;color:var(--mute)}
.fb{display:flex;gap:8px}.fb .btn{flex:1;padding:7px;font-size:12.5px;border-radius:12px}
.tgl{font:600 12px inherit;font-family:inherit;border:1.5px solid var(--line);background:var(--panel);color:var(--text);border-radius:999px;padding:3px 12px;cursor:pointer}
.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px}
.add{display:flex;gap:8px;padding:12px 20px 16px}.add input{flex:1;height:42px;margin:0;border-radius:12px}.add .btn{padding:8px 16px}
body[data-role=dep] .w{display:none!important}
.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:10px 20px;border-radius:999px;font-size:14px;font-weight:500;box-shadow:0 12px 24px -8px rgba(0,0,0,.4);z-index:9;opacity:0;pointer-events:none;transition:.25s}
.toast.on{opacity:1}
.me{cursor:pointer}
.tabs{display:flex;gap:8px;flex-wrap:wrap}
.tabs button{font:500 13.5px inherit;font-family:inherit;border:1px solid var(--line);background:var(--panel);color:var(--text);padding:6px 16px;border-radius:999px;cursor:pointer}
.tabs button.on{background:var(--acc);color:#fff;border-color:transparent;box-shadow:0 3px 0 rgba(0,0,0,.2)}
.tabs.sg button{padding:4px 14px;font-size:13px}
#dash{padding:0;background:none;border:0;box-shadow:none}
#dash .hero2{flex:1;min-height:600px;padding:80px 60px}
#dash .hl h2{font-size:44px}
.hl h2{font-size:36px;margin:0 0 10px;font-weight:600;letter-spacing:-.02em;line-height:1.2}.hl p{margin:0 0 20px;max-width:360px;opacity:.92;line-height:1.6}
.stk:before{background:#E9B872;transform:translate(26px,12px)}.stk:after{background:#E58E73;transform:translate(13px,6px)}
.gc h3{margin:0;font-size:22px;font-weight:600}.gc small{color:#6B817D;font-size:13px}
.hr{display:flex;align-items:center;gap:10px;background:#EFF5F3;border-radius:12px;padding:8px 12px;font-size:13px;margin-top:8px}.hr b{min-width:48px}.hr span.x{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

:root{--ov:rgba(255,255,255,.62);--photo:url(data:image/jpeg;base64,)}
@media(prefers-color-scheme:dark){:root{--ov:rgba(6,18,42,.72)}}
.top{height:68px;border-radius:0;border:0;border-bottom:1.5px solid var(--line);padding:0 28px;justify-content:space-between;flex-wrap:nowrap;background:var(--panel);box-shadow:0 8px 20px -14px rgba(30,70,160,.35)}
.top[hidden]{display:none}
.brandrow,.navr{display:flex;align-items:center}.navr{gap:22px}
.bn{font-weight:700;font-size:24px;letter-spacing:-.03em;color:var(--ink);cursor:pointer}
.co{display:flex;align-items:center;gap:10px;margin-left:14px;font-size:15px;font-weight:500;color:var(--ink)}
.co i{width:38px;height:38px;border-radius:10px;background:var(--ink);color:var(--panel);display:grid;place-items:center;font-style:normal;font-weight:600;font-size:14px}
.clock{display:flex;align-items:baseline;gap:14px}.cd{font-size:13px;color:var(--mute)}.ct{font-size:22px;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums}
.me{padding-left:22px;gap:12px}.me b{font-size:15px}
@media(max-width:760px){.co,.cd{display:none}.top{padding:0 14px}}
.tabs{align-items:center}.tabs i{font-style:normal;color:var(--mute)}
.tabs button{color:var(--acc);box-shadow:0 6px 14px -10px rgba(30,70,160,.5)}.tabs button.on{color:#fff}
.tabs.sg{margin-top:8px}.crumb2{margin-top:8px}.hrt{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.welcome{font-size:14px;color:var(--mute)}
.chip{display:inline-block;background:var(--nb);color:var(--nc);border-radius:999px;padding:2px 12px;font:500 12.5px inherit;font-family:inherit;margin:2px 6px 0 0;border:1px solid var(--line);cursor:pointer}
.strip .chip{display:inline-block}.fas{flex:1;min-width:200px}
body:not([data-role=admin]) .adm{display:none!important}
#login{min-height:640px;background:linear-gradient(115deg,rgba(6,18,42,.9) 0%,rgba(10,60,150,.6) 60%,rgba(45,134,255,.22) 100%),var(--photo) center/cover no-repeat;border:0}
#login .hero{background:none}
#dash{padding:0;gap:0;background:none;border:0;box-shadow:none;border-radius:0}
.hwrap{flex:1;position:relative;display:flex;flex-direction:column;padding:18px 36px 0;min-height:620px;border-radius:28px;overflow:hidden;border:1.5px solid var(--line);background:linear-gradient(var(--ov),var(--ov)),var(--photo) center/cover no-repeat;box-shadow:inset 0 2px 0 var(--hl),var(--sh)}
.hcr{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.hcr .welcome{color:var(--ink);font-weight:500}
.hmain{flex:1;display:flex;align-items:center;justify-content:space-between;gap:30px;flex-wrap:wrap;padding:20px 28px 90px}
.htxt{max-width:430px}.htxt h2{margin:0 0 12px;font-size:46px;font-weight:700;letter-spacing:-.03em;line-height:1.1;color:var(--ink)}.htxt p{margin:0 0 22px;font-size:16px;line-height:1.65;color:var(--text)}
.hb{font-family:inherit;font-weight:600;font-size:14px;color:var(--ink);background:var(--panel);border:1.5px solid var(--line);border-radius:999px;padding:8px 26px;cursor:pointer;box-shadow:0 6px 14px -8px rgba(30,70,160,.5)}
.hstack{position:relative;width:300px;height:400px;flex:none;margin-right:70px}
.hc{position:absolute;inset:0;transform-origin:left center;border-radius:28px;padding:22px;background:var(--cb);border:1.5px solid var(--cd2);box-shadow:0 18px 30px -18px var(--kc),inset 0 2px 0 var(--hl);transition:transform .4s,opacity .4s;display:flex;flex-direction:column;gap:6px}
.hc.c1{--cb:var(--k1);--cd2:var(--k1b);--ki:var(--k1i);--kic:var(--k1ic);--kc:var(--k1c)}.hc.c2{--cb:var(--k2);--cd2:var(--k2b);--ki:var(--k2i);--kic:var(--k2ic);--kc:var(--k2c)}.hc.c3{--cb:var(--k3);--cd2:var(--k3b);--ki:var(--k3i);--kic:var(--k3ic);--kc:var(--k3c)}
.hc.p0{transform:none;z-index:3}.hc.p1{transform:translate(30px,0) scale(.96);z-index:2}.hc.p2{transform:translate(60px,0) scale(.92);z-index:1}
.hic{width:52px;height:52px;border-radius:16px;background:var(--ki);color:var(--kic);display:grid;place-items:center;box-shadow:inset 0 2px 0 rgba(255,255,255,.55),0 8px 14px -6px var(--kc)}.hic svg{width:28px;height:28px}
.hc h4{margin:8px 0 0;font-size:24px;font-weight:700;letter-spacing:-.02em;color:var(--ink)}.hc .s{font-size:13px;color:var(--text)}
.mini{display:flex;flex-direction:column;gap:8px;margin-top:14px}.mini div{display:flex;justify-content:space-between;align-items:center;gap:8px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:8px 12px;font-size:13px;color:var(--ink)}
.bigp{font-size:68px;font-weight:700;color:var(--ink);line-height:1;margin-top:18px;letter-spacing:-.03em}
.avs{display:flex;margin-top:16px;padding-left:8px}.avs i{width:38px;height:38px;border-radius:50%;border:2px solid var(--panel);margin-left:-8px;display:grid;place-items:center;color:#fff;font-style:normal;font-size:12px;font-weight:600}
.harr{position:absolute;left:0;right:0;bottom:26px;display:flex;justify-content:center;gap:26px}
.harr button{width:50px;height:50px;border-radius:14px;border:1.5px solid var(--line);background:var(--panel);color:var(--ink);font-family:inherit;font-size:20px;font-weight:700;cursor:pointer;box-shadow:0 8px 16px -8px rgba(30,70,160,.5)}
@media(max-width:700px){.htxt h2{font-size:34px}.hstack{margin-right:50px}}
#keluar,#fkeluar{--acc:var(--a2)}#disp,#fdisp{--acc:var(--a3)}
.top{position:relative;z-index:10}
.meb{position:relative}
.menu{position:absolute;right:0;top:calc(100% + 12px);min-width:200px;background:var(--panel);border:1.5px solid var(--line);border-radius:16px;padding:8px;box-shadow:inset 0 2px 0 var(--hl),0 20px 30px -16px rgba(11,27,63,.45);z-index:20}
.menu[hidden]{display:none}
.mi{display:block;width:100%;text-align:left;background:none;border:0;color:var(--rc);font:600 14px inherit;font-family:inherit;padding:10px 14px;border-radius:10px;cursor:pointer}.mi:hover{background:var(--rb)}
