  if(m&&m.st==='baru')m.st='dis';acts.unshift(['Disposisi '+s+' ke '+V('d-to'),'Baru saja']);return 1},
 user(){if(!V('u-nm'))return toast('Isi nama pengguna');users.push([V('u-nm'),V('u-ro'),V('u-dp'),V('u-st')==='Aktif'?1:0]);acts.unshift(['Pengguna '+V('u-nm')+' didaftarkan','Baru saja']);return 1},
 keluar(){if(!V('k-no')||!V('k-to')||!V('k-sub'))return toast('Lengkapi nomor surat, tujuan, dan perihal');
  const f=$('k-f').files[0];keluar.unshift({no:V('k-no'),cat:V('k-cat'),to:V('k-to'),sub:V('k-sub'),tgl:V('k-tgl'),dep:V('k-dep'),f:f&&f.name});
  acts.unshift(['Surat keluar '+V('k-no')+' diarsipkan','Baru saja']);return 1}};
const NAV=[['masuk','Surat Masuk'],['disp','Disposisi'],['keluar','Surat Keluar'],['arsip','Arsip'],['user','Pengguna','admin'],['master','Departemen & Kategori','admin']];
const RL={admin:['Andi Pratama','Admin','AP'],sek:['Dewi Rahayu','Sekretaris','DR'],dep:['Budi Santoso','Departemen · Keuangan','BS']};
const PAR={fmasuk:'masuk',fdisp:'disp',fkeluar:'keluar'};
function setRole(r){role=r;document.body.dataset.role=r;const x=RL[r];$('mn').textContent=x[0];$('mr').textContent=x[1];$('av').textContent=x[2];$('hw').textContent=x[0];
Q('.wn').forEach(e=>e.textContent=x[0])}
const DET={admin:['masuk','disp','keluar','arsip','user','master'],sek:['masuk','disp','keluar','arsip'],dep:['masuk','disp','keluar','arsip']};
const LB={fmasuk:'Surat Masuk',fkeluar:'Surat Keluar',fdisp:'Disposisi',fuser:'Pengguna',masuk:'Surat Masuk',disp:'Disposisi',keluar:'Surat Keluar',arsip:'Arsip Digital',user:'Pengguna',master:'Departemen & Kategori'};
const PARF={fmasuk:'masuk',fdisp:'disp',fkeluar:'keluar',fuser:'user'};
function tabs(id){const g=id==='dash'?'dash':'det',cur=PARF[id]||id;
Q('[data-tabs]').forEach(e=>e.innerHTML=[['dash','Dashboard','dash'],['det','Detail',DET[role][0]]].map(t=>`<button data-go="${t[2]}"${t[0]===g?' class="on"':''}>${t[1]}</button>`).join('<i>/</i>'));
Q('[data-seg]').forEach(e=>e.innerHTML=DET[role].map(k=>`<button data-go="${k}"${k===cur?' class="on"':''}>${LB[k]}</button>`).join(''))}
function show(id){if(id[0]==='f')forms();document.querySelectorAll('.body').forEach(s=>s.classList.toggle('on',s.id===id));$('top').hidden=id==='login';tabs(id);
 Q('.nav button').forEach(b=>b.classList.toggle('on',b.dataset.go===(PAR[id]||id)));scrollTo(0,0)}
function doLogout(){$('logout-form').submit()}
document.addEventListener('click',e=>{const t=e.target,g=t.closest('[data-go]');
if(t.closest('#me')){const m=$('menu');m.hidden=!m.hidden;$('me').setAttribute('aria-expanded',String(!m.hidden));return}
if(t.closest('#lo-out')){$('menu').hidden=true;$('mdl').hidden=false;$('lo-yes').focus();return}
if(t.closest('#lo-no')||t.id==='mdl'){$('mdl').hidden=true;return}
if(t.closest('#lo-yes')){$('mdl').hidden=true;doLogout();return}
if(!t.closest('#menu'))$('menu').hidden=true;
 const sv = t.closest('[data-save]');
const u = t.closest('[data-u]');
const ad = t.closest('[data-add]');
const dl = t.closest('[data-dl]');
const dp = t.closest('[data-disp]');
const tr = t.closest('#t-masuk tr[data-i]');
const dispTr = t.closest('#t-disp tbody tr[data-i]');
const outTr = t.closest('#t-keluar tbody tr[data-i]');
 if(sv){const k=sv.dataset.save;if(SV[k]()){render();show(k);toast('Tersimpan')}return}
 if(u){users[+u.dataset.u][3]^=1;render();toast('Status akun diperbarui');return}
 if(ad){const k=ad.dataset.add,v=V('n-'+k);if(!v)return toast('Isi nama terlebih dahulu');(k==='dep'?deps:cats).push(v);$('n-'+k).value='';render();toast('Ditambahkan');return}
 if(dl){toast('Membuka '+dl.dataset.dl);return}
 if (dispTr) {
    const disposition = disp[Number(dispTr.dataset.i)];

    if (disposition && disposition.url) {
        window.location.href = disposition.url;
    } else {
        toast('Data detail disposisi tidak ditemukan');
    }

    return;
}
 if (dp) {
    const disposition = disp[Number(dp.dataset.disp)];

    if (!disposition || !disposition.id) {
        toast('Data disposisi tidak ditemukan');
        return;
    }

    const detailUrl = @json(route('dispositions.show', ['disposition' => 'DISPOSITION_ID']));

    window.location.href = detailUrl.replace(
        'DISPOSITION_ID',
        disposition.id
    );

    return;
}
 if(t.closest('[data-h]')){hi=(hi+ +t.closest('[data-h]').dataset.h+3)%3;pos();return}
 if (dispTr) {
    const disposition = disp[Number(dispTr.dataset.i)];

    if (disposition?.url) {
        window.location.href = disposition.url;
    } else {
        toast('Data detail disposisi tidak ditemukan');
    }

    return;
}
 if(tr){
    const letter = masuk[+tr.dataset.i];

    if(letter?.url){
        window.location.href = letter.url;
    }

    return;
}
 if(outTr){
  const letter=keluar[+outTr.dataset.i];
  if(letter?.url){window.location.href=letter.url;}
  return;
 }
 if(g)show(g.dataset.go)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('menu').hidden=true;$('mdl').hidden=true}
 if((e.key==='Enter'||e.key===' ')&&document.activeElement.id==='me'){e.preventDefault();$('me').click()}});
document.addEventListener('input',e=>{if(!e.target.classList.contains('search'))return;const q=e.target.value.toLowerCase();
 e.target.closest('.pnl').querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))});
function clk(){const d=new Date();$('cd').textContent=d.toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('ct').textContent=d.toLocaleTimeString('id-ID',{hour12:false}).replace(/\./g,':')}
clk();setInterval(clk,1000);
const R0={admin:'admin',sekretaris:'sek',departemen:'dep'}[String(AUTH.role).toLowerCase()]||'dep';
RL[R0][0]=AUTH.name;
setRole(R0);render();forms();show('dash');
</script>
</body>
</html>
